import {span,start,end,take} from './perf.js';
import {TrialRecorder} from './trial-recorder.js';
import {ExportJobs} from './export-jobs.js';
import {exportCopy,safeNotice,noticeKind,traceSteps,enterSheet,leaveSheet,focusDimension,exportBusy} from './ui-theme.js';
import {project,sample,element,pageOf,newPage,clone,uid,classes,bounds,translate} from './core.js';
import {Editor} from './commands.js';import {LocalStore} from './storage.js';import {VisionJobs} from './vision.js';
import {drawingSvg,shape,selection,hit,esc} from './render.js';import {icon} from './icons.js';
import {importFile} from './importers.js';import {exportFile,formats} from './exporters.js';import {downloadOrShare,capturePhoto} from './device.js';
import {initShell,isNative,nativeHealth} from './shell.js';
const app=document.querySelector('#app'),portal=document.querySelector('#portal'),store=new LocalStore(),vision=new VisionJobs();
let editor=null,screen='home',projects=[],selected=null,mode='select',viewMode='drawing',format='pptx',includePhoto=false,includeOriginal=false,savedRevision=-1,saveState='unsaved',panel=null,candidate=null,search='',busy=false;
let elementNodes=new Map();let reviewTarget=null;const exportJobs=new ExportJobs();
let trial=null,pendingTrial=null,restoredTrialReport=null;const historyWarnings=new Set();
let gestureBusy=false;
let toastTimer,suppressBackdropUntil=0,autosaveTimer,swRegistration,installPrompt,drawKey=null,listIds=null,listOffset=0,lastOpenedId=null;
const saveError=e=>e?.name==='QuotaExceededError'?'端末の空き容量が不足しています':/別の画面/.test(e?.message||'')?'別の画面で案件が更新されています。再読込して確認してください':/整合性|保存データ|履歴/.test(e?.message||'')?'保存内容を確認できません。元データを保全し、復旧コピーを使用してください':'端末に保存できませんでした';
const toast=t=>{const n=document.querySelector('#toast');n.textContent=safeNotice(t);n.dataset.kind=noticeKind(t);n.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.style.display='none',5500);};
const doc=()=>editor.doc,p=()=>pageOf(doc()),src=()=>doc().sources.find(s=>s.id===p().sourceId);
const btn=(a,label,i='',cls='',extra='')=>`<button type="button" data-action="${a}" class="${cls}" ${extra}>${i?icon(i):''}${label}</button>`;
const statusText=()=>saveState==='saving'?'保存中…':saveState==='failed'?'保存失敗':savedRevision===doc()?.revision?'保存済み':'未保存';
function statusHtml(){return `<span class="status ${saveState==='failed'?'failed':savedRevision===doc()?.revision?'':'unsaved'}">${statusText()}</span>`;}
function nav(active){return `<nav class="bottom-nav" aria-label="メイン">${[['home','図面','home'],['materials','素材','box'],['settings','設定','settings']].map(([a,t,i])=>btn(a,t,i,active===a?'active':'',`aria-current="${active===a?'page':'false'}"`)).join('')}</nav>`;}
function thumbnail(d){const pg=pageOf(d),s=d.sources.find(s=>s.id===pg.sourceId);return s?.workImage?`<img alt="${esc(d.title)}の作業用画像" src="${s.workImage}">`:drawingSvg({...pg,elements:pg.elements.slice(0,60)});}
function home(){const tHome=start();const list=projects.filter(d=>d.title.toLowerCase().includes(search.toLowerCase())),last=projects.find(d=>d.id===lastOpenedId)||projects[0];
 app.innerHTML=`<main class="screen home-screen"><header class="home-header"><div class="brand-lockup"><span class="brand-symbol" aria-hidden="true">V</span><span class="brand">VDRAW<span class="brand-sub">MOBILE WORKSPACE</span></span></div><span class="workspace-note">${icon('save')}端末内ワークスペース</span><h1>図面を、現場の力に。</h1><p class="muted">記録から編集、共有まで。</p></header>${btn('new','新しい図面を作る','plus','primary full create-main')}<div class="import-shortcuts" aria-label="資料から始める">${[['camera','写真から','camera'],['document','PDFから','file'],['photo','画像から','image'],['open-projects','図面を開く','folder']].map(([a,t,i])=>btn(a,t,i,'shortcut')).join('')}</div>${last?`<button class="resume" data-action="open" data-id="${last.id}"><span class="resume-icon">${icon('clock')}</span><span class="resume-copy"><span class="eyebrow">CONTINUE DRAWING</span><strong>${esc(last.title)}</strong><span class="small">${esc(pageOf(last).name)} · 続きから編集</span></span>${icon('chevron')}</button>`:''}<div class="sectionhead row spread"><div><span class="eyebrow">RECENT PROJECTS</span><h2>最近の図面</h2></div><span class="count-label">${list.length}件</span></div>${projects.length?`<div class="searchbox">${icon('search')}<input id="search" placeholder="図面名で検索" aria-label="図面名で検索" value="${esc(search)}"></div>`:`<input id="search" value="${esc(search)}" aria-label="図面名で検索" hidden>`}${store.issues.length?`<div class="card stack warning"><h2>保存内容の確認が必要です</h2><p>元データは保全しています。直前の保存から別の図面として復旧できます。</p>${store.issues.map(i=>btn('recover','復旧コピーを作る','file','secondary full',`data-id="${i.id}"`)).join('')}</div>`:''}<div class="projects">${list.map(d=>`<button class="project-card" data-action="open" data-id="${d.id}" aria-label="${esc(d.title)}を続きから編集"><div class="thumb">${thumbnail(d)}${d.sample?'<span class="tag">操作サンプル</span>':''}</div><div class="cardbody"><h3>${esc(d.title)}</h3><p class="muted small">${d.pages.length}ページ · ${new Date(d.updatedAt).toLocaleString('ja-JP',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}</p><div class="row spread"><span class="status">保存済み</span><span class="project-open">続きから編集 ${icon('chevron')}</span></div>${d.importWarnings.length?'<span class="tag warning compact">読込内容を要確認</span>':''}</div></button>`).join('')||`<div class="empty"><span class="empty-symbol">${icon('file')}</span><h3>${search?'一致する図面がありません':'最初の図面を作成しましょう'}</h3><p>${search?'別の名前で検索してください。':'写真・PDF・画像、または白紙から始められます。'}</p></div>`}</div><div class="sample-entry">${btn('sample','操作サンプルを試す','file','text-button')}<p class="small muted">合成図形です。写真認識の結果ではありません。</p></div></main>${nav('home')}`;
 end('home.build.dom',tHome);document.querySelector('#search').addEventListener('input',e=>{search=e.target.value;const focus=e.target.selectionStart;home();const input=document.querySelector('#search');input.focus();input.setSelectionRange(focus,focus)});
}
function edit(){const tEdit=start();gestureBusy=false;screen='edit';app.innerHTML=`<main class="editor"><header class="editor-header">${btn('back','','back','icon-button','aria-label="図面一覧へ戻る"')}<button class="title-button" data-action="pages" title="${esc(doc().title)} / ${esc(p().name)}"><strong>${esc(doc().title)}</strong>${statusHtml()}</button>${btn('undo','','undo','icon-button','aria-label="取り消し" '+(!editor.undoStack.length?'disabled':''))}${btn('redo','','redo','icon-button','aria-label="やり直し" '+(!editor.redoStack.length?'disabled':''))}${btn('export','','export','icon-button accent','aria-label="書き出し"')}</header><div class="view-bar"><div class="segmented" aria-label="図面表示">${[['photo','元写真'],['drawing','図面'],['overlay','重ねる']].map(([a,t])=>btn('view-'+a,t,'',viewMode===a?'active':'',`aria-pressed="${viewMode===a}"`)).join('')}</div>${btn('display','表示','layers','view-options','aria-label="表示と下書きの設定"')}</div><section class="canvas-wrap" aria-label="図面キャンバス"><svg id="stage" class="stage" role="application" aria-label="タップで選択、一本指で画面移動、二本指で拡大" tabindex="0"><g id="scene-group"></g></svg><span class="canvas-note">${mode==='move'?'対象移動モード':doc().sample?'操作サンプル':p().calibration.status==='UNSCALED'?'未校正 · 図面座標':'対象限定の寸法'}</span><div class="canvas-bottom">${btn('pages',`${doc().pages.length}ページ`,'file','canvas-action','aria-label="案件とページ"')}${btn('fit','全体','eye','canvas-action')}${btn('save','保存','save','canvas-action save-action','aria-label="端末に保存"')}</div><span class="zoom" id="zoom-label"></span></section><nav class="editor-tools" aria-label="編集ツール">${btn('select','選択','select',mode==='select'?'active':'',`aria-pressed="${mode==='select'}"`)}${btn('insert','線','line','','data-kind="line" aria-label="線を追加"')}${btn('dimension','寸法','ruler','','aria-label="寸法を追加" aria-haspopup="dialog"')}${btn('insert','文字','text','','data-kind="text" aria-label="文字を追加"')}${btn('material','素材','box','','aria-haspopup="dialog"')}${btn('add','図形','plus','','aria-haspopup="dialog"')}</nav></main>`;
 end('editor.root.dom',tEdit);const stageAtRender=document.querySelector('#stage');requestAnimationFrame(()=>{if(stageAtRender!==document.querySelector('#stage'))return;draw();const tAttach=start();attachGestures();end('editor.events.register',tAttach);});
}
function geometry(){const stage=document.querySelector('#stage');if(!stage)return null;const r=stage.getBoundingClientRect(),pg=p(),fit=Math.min((r.width-32)/pg.canvas.width,(r.height-32)/pg.canvas.height),v=pg.view||{x:0,y:0,scale:1};return {r,fit,k:fit*v.scale,tx:(r.width-pg.canvas.width*fit*v.scale)/2+v.x,ty:(r.height-pg.canvas.height*fit*v.scale)/2+v.y};}
function draw(force=false){const g=geometry();if(!g)return;const n=document.querySelector('#scene-group');n.setAttribute('transform',`translate(${g.tx} ${g.ty}) scale(${g.k})`);
 const photo=(viewMode==='photo'||viewMode==='overlay')&&src()?.workImage,drawing=viewMode!=='photo';
 const key=[p().id,viewMode].join(':');if(force||key!==drawKey||!n.firstChild){drawKey=key; const tSVG=start();const svg=`<rect width="${p().canvas.width}" height="${p().canvas.height}" fill="white"/>${photo?`<image href="${esc(src().workImage)}" width="${p().canvas.width}" height="${p().canvas.height}" preserveAspectRatio="xMidYMid meet"/>`:''}<g data-drawing="objects" opacity="${viewMode==='overlay'?.75:1}">${drawing?p().elements.filter(e=>e.visible!==false).map(shape).join(''):''}</g><g data-ui-only="selection"></g>`;end('render.svg.string',tSVG);const tDOM=start();n.innerHTML=svg;end('render.svg.dom',tDOM);elementNodes=new Map();
 }const tSelection=start();const e=selected&&p().elements.find(e=>e.id===selected),ui=n.querySelector('[data-ui-only=selection]');if(ui)ui.innerHTML=drawing&&e&&e.visible!==false?selection(e):'';end('render.selection.dom',tSelection);document.querySelector('#zoom-label').textContent=Math.round(p().view.scale*100)+'%';
}
function patchShape(id){const t=start(),e=p().elements.find(e=>e.id===id),node=elementNodes.get(id)||document.querySelector('[data-drawing=objects]')?.children[p().elements.filter(e=>e.visible!==false).findIndex(e=>e.id===id)];if(e&&node&&node.isConnected&&e.visible!==false){const temp=document.createElementNS("http://www.w3.org/2000/svg","svg");temp.innerHTML=shape(e);const replacement=temp.firstElementChild;node.replaceWith(replacement);elementNodes.set(id,replacement);}else draw(true);end('render.element.dom',t);}
function restoreDrawing(before){
 const previous=pageOf(before),next=p();
 const old=previous.elements.filter(e=>e.visible!==false),now=next.elements.filter(e=>e.visible!==false);
 if(screen!=='edit'||previous.id!==next.id||JSON.stringify(previous.canvas)!==JSON.stringify(next.canvas)||old.length!==now.length||old.some((e,i)=>e.id!==now[i].id)||JSON.stringify(before.sources)!==JSON.stringify(doc().sources)){edit();return;}
 const t=start();const changed=now.filter((e,i)=>JSON.stringify(e)!==JSON.stringify(old[i]));end('render.undo.diff',t);
 if(changed.length>50)draw(true);else for(const e of changed)patchShape(e.id);
 const title=document.querySelector('.title-button strong');if(title)title.textContent=doc().title+' / '+next.name;
 const pageButton=document.querySelector('.canvas-bottom [data-action=pages]');if(pageButton)pageButton.textContent=next.name+' / '+doc().pages.length;
 draw();refreshStatus();
}
function scheduleSave(){clearTimeout(autosaveTimer);autosaveTimer=setTimeout(()=>gestureBusy?scheduleSave():save(true),700);}
function markDirty(){saveState='unsaved';refreshStatus();scheduleSave();}
function refreshStatus(){const u=document.querySelector('[data-action=undo]'),r=document.querySelector('[data-action=redo]');if(u)u.disabled=!editor.undoStack.length;if(r)r.disabled=!editor.redoStack.length;const s=document.querySelector('.editor-header .status');if(s){s.textContent=statusText();s.className='status '+(saveState==='failed'?'failed':savedRevision===doc().revision?'':'unsaved');s.dataset.state=saveState==='saving'?'saving':saveState==='failed'?'failed':savedRevision===doc().revision?'saved':'unsaved';s.setAttribute('role','status');}}
function change(label,fn){if(editor.apply(label,fn)){markDirty();}edit();}
async function save(quiet=false){if(!editor)return true;clearTimeout(autosaveTimer);const owner=editor,snapshot=owner.doc,history=owner.history(),trialOwner=trial?.projectId===owner.doc.id?trial:null;if(trialOwner)trialOwner.saving(snapshot);saveState='saving';refreshStatus();try{const r=await store.save(snapshot,history);if(trialOwner){trialOwner.saved(true);try{await store.transaction('readwrite',x=>x.put(trialOwner.report(),'vision-trial-'+snapshot.id),'meta');}catch{trialOwner.recordPersistenceError='EVIDENCE_SAVE_FAILED';}}if(editor===owner){savedRevision=r;saveState=doc().revision===r?'saved':'unsaved';if(saveState==='unsaved')scheduleSave();}refreshStatus();if(store.lastSaveInfo?.id===snapshot.id&&store.lastSaveInfo.historyOmitted&&!historyWarnings.has(snapshot.id)){historyWarnings.add(snapshot.id);toast('図面は保存済みです。Undo履歴は容量上限により再開後に保持されません');}else if(!quiet)toast('端末に保存しました');return editor!==owner||savedRevision===doc().revision;}catch(e){if(trialOwner)trialOwner.saved(false);if(editor===owner){saveState='failed';refreshStatus();}toast('保存失敗：'+saveError(e)+'。画面を閉じずにバックアップか再試行を選んでください');return false;}}
async function open(id){clearTimeout(autosaveTimer);const session=await store.loadSession(id);await store.remember(id);lastOpenedId=id;editor=new Editor(session.doc,session.history);trial=null;pendingTrial=null;restoredTrialReport=doc().adoptions.length?await store.transaction('readonly',x=>x.get('vision-trial-'+id),'meta'):null;if(restoredTrialReport)trial=TrialRecorder.restore(restoredTrialReport,doc());savedRevision=doc().revision;saveState='saved';selected=null;mode='select';viewMode=src()?.workImage?'overlay':'drawing';edit();}
function begin(d){trial=null;pendingTrial=null;restoredTrialReport=null;clearTimeout(autosaveTimer);lastOpenedId=d.id;editor=new Editor(d);savedRevision=-1;saveState='unsaved';selected=null;mode='select';viewMode=src()?.workImage?'overlay':'drawing';edit();scheduleSave();}
function sheet(title,content,actions='',kind='',modal=true){document.querySelector('#toast').style.display='none';panel=kind||title;portal.innerHTML=`${modal?'<div class="panel-backdrop" data-action="dismiss" aria-hidden="true"></div>':''}<section class="sheet ${kind}" role="dialog" aria-modal="${modal}" aria-label="${esc(title)}"><div class="sheet-handle"></div><header class="sheet-head"><h2>${esc(title)}</h2>${btn('dismiss','','close','icon-button','aria-label="パネルを閉じる"')}</header><div class="sheet-content">${content}</div>${actions?`<footer class="sheet-actions">${actions}</footer>`:''}</section>`;enterSheet(modal);}
function dismiss(){leaveSheet();portal.innerHTML='';panel=null;draw();}
function newSheet(){sheet('新しい図面',`<p class="muted">資料を選ぶか、白紙から始めます。</p><div class="import-options">${[['camera','写真を撮る','camera','現場を撮影して読み込む'],['photo','写真・画像を選ぶ','image','端末内の画像を使う'],['document','PDF・既存図面を開く','file','PDF・PowerPoint・案件バックアップ'],['blank','白紙から作る','plus','線・寸法・文字を配置する']].map(([a,t,i,n])=>`<button class="option" data-action="${a}"><span class="option-icon">${icon(i)}</span><span><strong>${t}</strong><span class="muted">${n}</span></span>${icon('chevron')}</button>`).join('')}</div>`, '', 'import');}
function objectSheet(id){if(trial?.projectId===doc().id&&trial.pageId===doc().activePageId&&!trial.firstEdit)trial.start('MANUAL_EDIT');selected=id;const e=p().elements.find(e=>e.id===id);if(!e)return;draw();sheet('対象を編集',`<div class="object-summary"><span class="object-swatch" style="background:${e.fill==='none'?e.stroke:e.fill}"></span><span><strong>${esc(e.name)}</strong><span class="muted small">${esc(e.category)} · 図面上で選択中</span></span>${btn('move','移動','move','secondary')}</div><label>名称<input id="object-name" value="${esc(e.name)}" maxlength="160"></label>${e.kind==='text'?`<label>文字<input id="object-text" value="${esc(e.text)}"></label>`:''}<div class="row spread"><label>図面の実色<input id="object-color" type="color" value="${e.fill==='none'?e.stroke:e.fill}"></label><div class="colors">${['#BACFC7','#D8BEA0','#BFD6E4','#394C63'].map(c=>`<button class="swatch" data-action="swatch" data-color="${c}" aria-label="実色 ${c}"><span style="background:${c}"></span></button>`).join('')}</div></div><details class="detail-section"><summary>分類・線・重なり</summary><div class="stack"><label>分類<select id="object-class">${classes.map(c=>`<option ${c===e.category?'selected':''}>${c}</option>`).join('')}</select></label><div class="two-cols"><label>線の色<input id="object-stroke" type="color" value="${e.stroke}"></label><label>線幅（図面座標）<input id="object-width" type="number" min="0" max="30" step="0.5" value="${e.strokeWidth}"></label></div><div class="two-cols">${btn('hide',e.visible===false?'表示する':'非表示','eye','secondary')}${btn('forward','前面へ','layers','secondary')}${btn('backward','背面へ','layers','secondary')}</div></div></details><div class="two-cols">${btn('geometry','形・座標を修正','ruler','secondary')}${btn('delete-object','削除','trash','secondary danger')}</div><p class="small muted">削除や確定した変更は、取り消しで戻せます。</p>`,btn('dismiss','閉じる','','secondary')+btn('apply-object','変更を確定','check','primary'), 'object',false);}
function objectList(ids=null,offset=0){listIds=ids;listOffset=offset;const es=ids?p().elements.filter(e=>ids.includes(e.id)):p().elements;sheet(ids?'重なった対象を選択':'対象一覧',`<p class="muted">細い線や非表示の対象も、一覧から選択できます。</p><p class="small muted">${es.length}件 · ${Math.min(es.length,offset+1)}〜${Math.min(es.length,offset+100)}件を表示</p><div class="two-cols">${offset>0?btn("list-prev","前の100件","","secondary"):""}${es.length>offset+100?btn("list-next","次の100件","","secondary"):""}</div><div class="objectlist">${es.slice().reverse().slice(offset,offset+100).map(e=>`<button class="objectitem" data-action="object" data-id="${e.id}"><span class="dot" style="background:${e.fill==='none'?e.stroke:e.fill}"></span><span><strong>${esc(e.name)}</strong><br><span class="muted small">${esc(e.category)}${e.visible===false?' · 非表示':''}</span></span></button>`).join('')||'<p class="empty">対象はまだありません。</p>'}</div>`);}
function geometrySheet(){const e=p().elements.find(e=>e.id===selected),b=bounds(e);sheet('形・座標を修正',`<p class="muted">座標は図面上の値です。実寸ではありません。</p><div class="vertex-preview">${drawingSvg({...p(),canvas:{width:p().canvas.width,height:p().canvas.height},elements:[e]})}</div><div class="two-cols">${['x','y','w','h'].map(k=>`<label>${{x:'横位置',y:'縦位置',w:'幅',h:'高さ'}[k]}<input id="geom-${k}" type="number" step="1" value="${b[k]}"></label>`).join('')}</div>${e.kind==='polygon'?`<h3>頂点の数値修正</h3>${e.points.map(([x,y],i)=>`<div class="two-cols"><label>頂点${i+1} X<input class="vertex-x" type="number" value="${x}"></label><label>頂点${i+1} Y<input class="vertex-y" type="number" value="${y}"></label></div>`).join('')}`:''}${btn('geometry-zoom','選択対象を拡大','search','secondary')}`,btn('apply-geometry','座標を確定','check','primary'),'geometry');}
function pagesSheet(){sheet('案件・ページ',`<label>案件名<input id="project-title" value="${esc(doc().title)}" maxlength="160"></label>${btn('rename','案件名を保存','check','secondary')}<div class="objectlist">${doc().pages.map(pg=>`<button class="objectitem" data-action="page" data-id="${pg.id}">${icon('file')}<span>${esc(pg.name)}${pg.id===p().id?' · 編集中':''}</span></button>`).join('')}</div><label>現在のページ名<input id="page-name" value="${esc(p().name)}" maxlength="100"></label>${btn('rename-page','ページ名を保存','check','secondary')}${btn('add-page','白紙ページを追加','plus','secondary')}${btn('new','資料を新しい案件に読み込む','image','secondary')}${doc().importWarnings.map(t=>`<p class="warning">${esc(t)}</p>`).join('')}`);}
function dimensionSheet(){const target=selected&&p().elements.find(e=>e.id===selected);sheet('寸法を追加',`<div class="dimension-context"><span class="dimension-target">${target?drawingSvg({...p(),elements:[target]}):icon('ruler')}</span><span><strong>${target?esc(target.name):'図面に寸法を配置'}</strong><span class="muted small">選択対象・辺に限定した実測値</span></span></div><label class="dimension-label">実測した長さ<div class="numeric-input"><input id="dimension-value" type="number" inputmode="decimal" min="1" placeholder="未入力" aria-label="実測した長さ mm"><span>mm</span></div></label><details class="detail-section"><summary>表示名と適用範囲</summary><div class="stack"><label>表示名<input id="dimension-name" value="確認寸法"></label><p class="warning compact">未入力は未校正。写真全体や奥行きの縮尺は確定しません。</p></div></details>`,btn('dismiss','キャンセル','','secondary')+btn('add-dimension','寸法を配置','check','primary'),'dimension');focusDimension();}
function traceSheet(){const steps=traceSteps(src(),vision,trial?.report()||restoredTrialReport);sheet('図面の下書き',`<div class="trace-summary"><span class="option-icon">${icon('trace')}</span><div><h3>${vision.state==='BLOCKED'?'自動下書きは未接続です':'下書きの処理状況'}</h3><p class="muted">${vision.state==='BLOCKED'?'手動作図は引き続き利用できます。':'確認できた処理状態だけを表示します。'}</p></div></div><ol class="trace-steps">${steps.map((x,i)=>`<li data-state="${x.status}"><span class="step-index">${x.status==='PASS'?icon('check'):i+1}</span><strong>${x.label}</strong><span class="step-state">${x.text}</span></li>`).join('')}</ol><p class="small muted">写真の外部送信・処理の自動再実行はありません。</p>`,btn('dismiss','手動作図を続ける','select','primary'),'trace');}
function displaySheet(){sheet('表示と下書き',`<div class="two-cols">${btn('objects','対象一覧','layers','secondary')}${btn('fit','全体表示','eye','secondary')}</div><div class="gesture-guide"><span>${icon('move')}一本指で画面移動</span><span>${icon('search')}二本指で拡大・縮小</span></div><div class="section-divider"></div><h3>下書きと候補</h3>${btn('draft','下書きの処理状況','trace','primary full')}<p class="small muted">自動下書きは未接続。写真の外部送信なし。</p>${btn('candidate-sample','候補確認の操作サンプル','file','secondary full')}<p class="small muted">合成候補です。写真認識の結果ではありません。</p>${doc().candidates.length?'<h3>保存候補</h3>'+doc().candidates.map(c=>btn('candidate-open',`${c.kind==='operation-sample'?'操作サンプル':'候補'} · ${{pending:'要確認',adopted:'採用済み',discarded:'破棄済み'}[c.status]||'要確認'}`,'file','secondary full',`data-id="${c.id}"`)).join(''):''}<div class="two-cols">${btn('save','保存','save','secondary')}${btn('export','書き出し','export','secondary')}</div>`, '', 'display');}
function candidatePreview(view='drawing'){const context=vision.preview(doc(),candidate);const result=drawingSvg(context.page,context.source,{sourceVisible:view!=='drawing',drawingVisible:view!=='photo',overlay:view==='overlay'});const e=reviewTarget&&candidate.elements.find(e=>e.id===reviewTarget);return e&&view!=='photo'?result.replace('</svg>',`<g data-ui-only="candidate-selection">${selection(e)}</g></svg>`):result;}
function candidateSheet(){const c=candidate;reviewTarget=null;sheet('候補を確認',`<span class="tag">${c.kind==='operation-sample'?'操作サンプル · 実AI結果ではありません':c.kind==='protocol-fixture'?'接続手順の模擬データ':'要確認 · 自動では採用しません'}</span><div class="segmented" aria-label="候補の表示">${[['candidate-photo','元写真'],['candidate-drawing','図面'],['candidate-overlay','重ねる']].map(([a,t])=>btn(a,t,'',a==='candidate-drawing'?'active':'',`aria-label="候補 ${t}" aria-pressed="${a==='candidate-drawing'}"`)).join('')}</div><div id="candidate-preview" class="export-preview">${candidatePreview()}</div><p class="small muted">形・色・対象を確認してください。採用すると新しいページになり、元の図面は保持します。</p><div class="candidate-targets">${c.elements.map(e=>btn('review-target',`${esc(e.name)} <span class="muted small">${esc(e.category)}</span>`,'select','objectitem',`data-id="${e.id}" aria-pressed="false"`)).join('')}</div><div class="two-cols">${btn('keep-candidate','候補を保存','save','secondary')}${btn('discard-candidate','候補を破棄','trash','secondary danger')}</div>`,btn('adopt','採用する','check','secondary')+btn('candidate-edit','採用して修正','select','primary'),'candidate');}
async function measuredExport(d,f,options){const owner=trial?.projectId===d.id&&['pptx','dxf'].includes(f)?trial:null,stage=f.toUpperCase();if(owner)owner.start(stage);try{const blob=await exportFile(d,f,options);owner?.finish(stage);if(owner)try{await store.transaction('readwrite',x=>x.put(owner.report(),'vision-trial-'+d.id),'meta');}catch{owner.recordPersistenceError='EVIDENCE_SAVE_FAILED';}return blob;}catch(e){owner?.finish(stage,'FAILED','EXPORT_FAILED');throw e;}}
function diagnostics(){const report=trial?.report()||restoredTrialReport;sheet('Vision Diagnostics',`<p>実Claude / SAM：未接続。実写真推論の成功実績はありません。</p><p>保存済み試験記録：${report?'あり':'なし'}。モデル・時刻・件数だけを記録し、写真・名称・接続先・秘密情報は含めません。</p>${report?btn('trial-download','試験記録を保存','file','secondary full'):''}${trial?`<label>見落とし対象数<input id="trial-missed" type="number" min="0" value="0"></label><label>誤分類対象数<input id="trial-misclassified" type="number" min="0" value="0"></label><label>誤形状対象数<input id="trial-shapes" type="number" min="0" value="0"></label><label><input id="trial-attest" type="checkbox">写真と候補を本人が確認しました</label>${btn('trial-assess','目視確認を記録','check','secondary full')}`:''}<p>実機、モデルload、CUDA、checkpointは未確認。模擬試験を実AI成功に数えません。</p>`,'','vision-diagnostics');}
function exportScreen(){document.querySelector('#toast').style.display='none';screen='export';app.innerHTML=`<main class="screen export-screen"><div class="navline">${btn('edit','','back','icon-button','aria-label="図面へ戻る"')}<div><span class="eyebrow">EXPORT DRAWING</span><h1>書き出し</h1></div></div><div class="export-layout"><div class="export-preview">${drawingSvg(p(),src(),{sourceVisible:includePhoto})}<h2>${esc(doc().title)}</h2><p class="muted small">${doc().pages.length}ページ · 図面座標</p><p class="warning compact">未校正の図面。寸法は入力した対象に限定されます。</p></div><div><h2 class="export-heading">用途に合わせて選ぶ</h2><div class="export-grid">${formats.map(f=>{const copy=exportCopy[f.id]||[f.title,f.note];return `<button class="format ${f.id===format?'selected':''}" data-action="format" data-format="${f.id}" aria-pressed="${f.id===format}"><span class="format-code">${f.ext}</span><span class="format-copy"><strong>${copy[0]}</strong><span class="muted">${copy[1]}</span></span><span class="selection-indicator" aria-hidden="true">${f.id===format?icon('check'):''}</span></button>`}).join('')}</div><details class="detail-section export-options"><summary>写真の添付・バックアップ設定</summary><div class="stack"><label class="checklabel"><input id="include-photo" type="checkbox" ${includePhoto?'checked':''}>元写真を添付（作業用画像）</label><p class="small muted">作業用PNGには位置情報などを含めません。</p>${format==='json'?`<label class="checklabel"><input id="include-original" type="checkbox" ${includeOriginal?'checked':''}>原本もバックアップに含める</label><p class="warning compact">原本には顧客情報・位置情報が含まれる場合があります。</p>`:''}</div></details><div class="export-actions"><p class="export-status small muted" role="status">形式を選んで保存・共有</p><div class="export-action-buttons">${btn('download','ファイルを保存','export','primary full')}${btn('share','共有','share','secondary')}</div></div>${doc().exports.length?`<details class="detail-section"><summary>この図面の出力履歴</summary>${doc().exports.slice().reverse().map(e=>`<div class="history"><strong>${esc(e.format.toUpperCase())}</strong><span>${e.status==='downloaded'?'ダウンロード開始':e.status==='share-requested'?'共有画面へ受渡し':'共有完了'}</span><p class="muted small">${new Date(e.at).toLocaleString('ja-JP')}</p></div>`).join('')}</details>`:''}</div></div></main>`;
 document.querySelector('#include-photo').onchange=e=>{includePhoto=e.target.checked;exportScreen();};const io=document.querySelector('#include-original');if(io)io.onchange=e=>{includeOriginal=e.target.checked;};exportBusy(!!exportJobs.active);}
async function output(share){if(busy||exportJobs.active)return;const job=exportJobs.begin({owner:editor,document:doc(),format,options:{includePhoto,includeOriginal},share}),s=job.snapshot;busy=true;exportBusy(true);
 const owns=()=>exportJobs.owns(job,editor,doc()),cancel=()=>toast('図面が切り替わったか変更されたため、今回の出力を中止しました。現在の図面から再実行してください');
 try{toast('ファイルを作成中');const blob=await measuredExport(s.document,s.format,s.options);
  if(!owns()){cancel();return;}if(blob.type!==s.mime)throw Error('出力形式とファイル内容が一致しません');
  const result=await downloadOrShare(blob,s.name,s.share);
  if(!owns()){toast('ファイルは共有・保存へ渡しましたが、図面が変更されたため出力履歴を追加しませんでした');return;}
  const entry=exportJobs.history(job,result);doc().exports.push(entry);doc().revision++;markDirty();const ok=await save(true);
  if(editor!==job.owner)return;if(screen==='export')exportScreen();
  const delivered=result==='share-requested'?'共有画面へ渡しました':result==='downloaded'?'ダウンロードを開始しました':'共有しました';
  toast(ok?delivered+'。出力履歴を端末に保存しました':delivered+'が、出力履歴の端末保存に失敗しました');
 }catch(e){toast(e.name==='AbortError'?'共有をキャンセルしました':'出力失敗：'+safeNotice(e.message));}
 finally{if(exportJobs.release(job)){busy=false;exportBusy(false);}}}

function materials(editing=false){const options=[['机','rect','家具','#D8BEA0'],['椅子','rect','家具','#BACFC7'],['植栽','ellipse','植栽','#A9C293'],['設備','rect','設備','#BFD6E4'],['車','rect','車','#D5E3EF'],['汎用図形','polygon','汎用図形','#D5E3EF']];
 const content=options.map(([name,kind,category,color])=>`<button class="option" data-action="insert-material" data-name="${name}" data-kind="${kind}" data-class="${category}" data-color="${color}">${icon('box')}<span><strong>${name}</strong><span class="muted">編集可能な汎用記号</span></span></button>`).join('');
 if(editing)sheet('素材を配置',content);else{screen='materials';app.innerHTML=`<main class="screen stack"><h1>素材</h1><p class="muted">図面編集画面から配置できます。記号は対象に合わせて修正してください。</p>${options.map(([name,kind,c,col])=>`<div class="card row">${icon('box')}<span>${name} · ${c}</span></div>`).join('')}</main>${nav('materials')}`;}}
async function settings(){if(!isNative()&&navigator.serviceWorker){try{swRegistration=await navigator.serviceWorker.getRegistration()||swRegistration;}catch{}}screen='settings';app.innerHTML=`<main class="screen stack"><h1>設定</h1><div class="card stack"><h2>保存と通信</h2><p>端末内保存のみ。同期機能は未実装です。</p><p class="muted">${navigator.onLine?'オンライン':'オフライン'} · 通信復旧によるAI自動再実行はありません。</p><p class="muted small">端末故障・アプリ削除・ブラウザのデータ消去に備え、案件バックアップを保存してください。</p></div><div class="card stack"><h2>表示</h2>${btn('large-type',document.documentElement.classList.contains('large-type')?'標準の文字サイズ':'文字を大きくする','eye','secondary')}</div><div class="card stack"><h2>接続状況</h2><p>AI下書き：未接続<br>${isNative()?"端末ブリッジ接続（実機未確認）":"Webモード"}<br>カメラ：端末のファイル撮影経路<br>OS共有：${isNative()?"端末共有入口":"ブラウザ対応時"}</p>${btn('developer','開発者向け','settings','secondary')}</div><div class="card stack"><h2>アプリと保存領域</h2><p>VDRAW MOBILE 007 · 変更後700msで自動保存</p>${btn("persist","保存領域の保持を要求","save","secondary")}${btn("storage-info","保存容量を確認","file","secondary")}${installPrompt?btn("install","ホーム画面に追加","plus","secondary"):""}${btn("check-update","更新を確認","file","secondary")}${swRegistration?.waiting?btn("apply-update","保存して更新を適用","check","primary"):""}<p class="muted small">自動保存は端末の強制終了直前には完了しない場合があります。端末保存済みの表示を確認してください。</p></div></main>${nav('settings')}`;}
const number=id=>{const n=Number(document.querySelector('#'+id).value);if(!Number.isFinite(n))throw Error('数値を入力してください');return n;};
async function action(a,target){
 if(a==='open-projects'){sheet('図面を開く',`${projects.length?projects.map(d=>btn('open',esc(d.title),'file','option',`data-id="${d.id}"`)).join(''):'<p class="empty">保存した図面はまだありません。</p>'}${btn('document','既存図面ファイルを選ぶ','folder','secondary full')}`);return;}
 if(a==='review-target'){reviewTarget=target.dataset.id;document.querySelector('#candidate-preview').innerHTML=candidatePreview();for(const b of portal.querySelectorAll('[data-action=review-target]'))b.setAttribute('aria-pressed',String(b.dataset.id===reviewTarget));return;}
 if(a==='candidate-edit'){const id=reviewTarget;await action('adopt',target);requestAnimationFrame(()=>id?objectSheet(id):objectList());return;}
 switch(a){
 case 'home':case 'back':if(editor&&savedRevision!==doc().revision){if(!await save())return;}dismiss();selected=null;screen='home';projects=await store.list();home();break;
 case 'new':newSheet();break;case 'camera':if(isNative()){try{if(editor&&savedRevision!==doc().revision&&!await save())return;const f=await capturePhoto();if(f){dismiss();begin(await importFile(f));}}catch(e){toast('撮影を利用できません。写真から選択して続けられます');}break;}document.querySelector('#camera-input').click();break;case 'photo':case 'document':document.querySelector('#'+a+'-input').click();break;
 case 'recover':{const d=await store.recoverAsCopy(target.dataset.id);begin(d);await save();break;}
 case 'delete-object':{editor.remove(selected);markDirty();selected=null;mode='select';dismiss();edit();toast('対象を削除しました。取り消しで戻せます');break;}
 case 'blank':if(editor&&savedRevision!==doc().revision&&!await save())return;dismiss();begin(project());break;
 case 'sample':if(editor&&savedRevision!==doc().revision&&!await save())return;dismiss();begin(sample());await save();edit();break;
 case 'open':if(editor&&savedRevision!==doc().revision&&!await save())return;dismiss();await open(target.dataset.id);break;
 case 'save':await save();break;case 'edit':dismiss();edit();break;case 'export':dismiss();includePhoto=false;includeOriginal=false;exportScreen();break;
 case 'dismiss':dismiss();break;
 case 'undo':{const before=doc();dismiss();if(editor.undo()){if(trial?.projectId===doc().id)trial.actions++;selected=null;markDirty();restoreDrawing(before);}break;}
 case 'redo':{const before=doc();dismiss();if(editor.redo()){if(trial?.projectId===doc().id)trial.actions++;selected=null;markDirty();restoreDrawing(before);}break;}
 case 'view-photo':case 'view-drawing':case 'view-overlay':if(a!=='view-drawing'&&!src()?.workImage){toast('このページに元写真はありません');return;}dismiss();viewMode=a.slice(5);edit();break;
 case 'select':mode='select';selected=null;dismiss();objectList();break;
 case 'list-next':objectList(listIds,listOffset+100);break;case 'list-prev':objectList(listIds,Math.max(0,listOffset-100));break;
 case 'objects':objectList();break;case 'object':dismiss();objectSheet(target.dataset.id);break;
 case 'swatch':document.querySelector('#object-color').value=target.dataset.color;break;
 case 'apply-object':{const e=p().elements.find(e=>e.id===selected),before=clone(e),name=document.querySelector('#object-name').value,color=document.querySelector('#object-color').value,stroke=document.querySelector('#object-stroke').value,strokeWidth=number('object-width');if(strokeWidth<0||strokeWidth>30)throw Error('線幅は0〜30で入力してください');editor.update(selected,{name,category:document.querySelector('#object-class').value,fill:e.fill==='none'?'none':color,stroke:e.fill==='none'?color:stroke,strokeWidth,...(e.kind==='text'?{text:document.querySelector('#object-text').value}:{})});if(trial?.projectId===doc().id&&trial.pageId===doc().activePageId)trial.edit(before,p().elements.find(e=>e.id===selected));patchShape(selected);markDirty();dismiss();break;}
 case 'move':mode='move';dismiss();edit();toast('対象移動モード。ドラッグで選択対象を移動します');break;
 case 'hide':editor.update(selected,{visible:p().elements.find(e=>e.id===selected).visible===false});markDirty();dismiss();selected=null;edit();break;
 case 'forward':case 'backward':editor.reorder(selected,a==='forward'?1:-1);markDirty();dismiss();edit();break;
 case 'geometry':geometrySheet();break;
 case 'geometry-zoom':{const b=bounds(p().elements.find(e=>e.id===selected)),g=geometry();p().view.scale=Math.min(8,Math.min(g.r.width/(b.w+100),g.r.height/(b.h+100))/g.fit);const k=g.fit*p().view.scale;p().view.x=(p().canvas.width/2-b.x-b.w/2)*k;p().view.y=(p().canvas.height/2-b.y-b.h/2)*k;dismiss();draw();toast('拡大後は対象をタップし、数値で頂点を修正できます');break;}
 case 'apply-geometry':{const e=p().elements.find(e=>e.id===selected),before=clone(e),b=bounds(e),x=number('geom-x'),y=number('geom-y'),w=number('geom-w'),h=number('geom-h');if(w<0||h<0||w>10000||h>10000)throw Error('幅・高さは0〜10000です');
  if(e.kind==='arc'&&w!==h)throw Error('円弧は幅と高さを同じ値にしてください');const patch={x,y,w,h};if(e.kind==='polygon'){patch.points=[...document.querySelectorAll('.vertex-x')].map((n,i)=>[Number(n.value),Number(document.querySelectorAll('.vertex-y')[i].value)]);const valuesChanged=JSON.stringify(patch.points)!==JSON.stringify(e.points);if(!valuesChanged)patch.points=e.points.map(([a,bv])=>[x+(a-b.x)/(b.w||1)*w,y+(bv-b.y)/(b.h||1)*h]);}
  editor.update(selected,patch);if(trial?.projectId===doc().id&&trial.pageId===doc().activePageId)trial.edit(before,p().elements.find(e=>e.id===selected));patchShape(selected);markDirty();dismiss();break;}
 case 'add':sheet('図形を追加',`<div class="two-cols">${[['rect','四角形'],['ellipse','円・楕円'],['line','線'],['arc','円弧'],['polygon','多角形'],['text','文字']].map(([k,t])=>btn('insert',t,'plus','secondary',`data-kind="${k}"`)).join('')}</div>`);break;
 case 'insert':{const kind=target.dataset.kind,e=element(kind,{rect:'四角形',ellipse:'楕円',line:'線',arc:'円弧',polygon:'多角形',text:'文字'}[kind],kind==='line'?{fill:'none',h:0}:kind==='arc'?{fill:'none',w:160,h:160,startAngle:0,endAngle:180}:kind==='polygon'?{points:[[260,220],[500,240],[460,380],[280,365]]}:kind==='text'?{text:'新しい文字',fill:'#394C63'}:{});editor.add(e);markDirty();dismiss();viewMode='drawing';edit();requestAnimationFrame(()=>objectSheet(e.id));break;}
 case 'material':materials(true);break;
 case 'insert-material':{const e=element(target.dataset.kind,target.dataset.name,{category:target.dataset.class,fill:target.dataset.color,...(target.dataset.kind==='polygon'?{points:[[260,220],[500,240],[460,380],[280,365]]}:{})});editor.add(e);markDirty();dismiss();viewMode='drawing';edit();requestAnimationFrame(()=>objectSheet(e.id));break;}
 case 'dimension':dimensionSheet();break;case 'add-dimension':{const v=document.querySelector('#dimension-value').value,value=v?number('dimension-value'):null;if(value!==null&&value<=0)throw Error('実測寸法は正数を入力してください');const e=element('dimension',document.querySelector('#dimension-name').value,{x:300,y:650,w:400,h:0,fill:'none',text:value===null?'寸法未入力':value+' mm',dimension:{status:value===null?'UNSCALED':'MANUAL',valueMm:value,scope:'selected-edge-only',referenceElementId:selected||null,planeId:null,doesNotCalibratePage:true}});editor.add(e);markDirty();dismiss();viewMode='drawing';edit();break;}
 case 'display':displaySheet();break;case 'pages':pagesSheet();break;
 case 'page':doc().activePageId=target.dataset.id;selected=null;mode='select';viewMode='drawing';doc().revision++;markDirty();dismiss();edit();break;
 case 'add-page':change('ページの追加',d=>{const pg=newPage('図面 '+(d.pages.length+1));d.pages.push(pg);d.activePageId=pg.id;});selected=null;dismiss();break;
 case 'rename':{const value=document.querySelector('#project-title').value.trim();if(!value)throw Error('案件名を入力してください');change('案件名の変更',d=>d.title=value);dismiss();break;}
 case 'rename-page':{const value=document.querySelector('#page-name').value.trim();if(!value)throw Error('ページ名を入力してください');change('ページ名の変更',d=>pageOf(d).name=value);dismiss();break;}
 case 'fit':p().view={x:0,y:0,scale:1};doc().revision++;markDirty();dismiss();draw();break;
 case 'draft':try{await vision.draft();}catch(e){toast(e.message);}traceSheet();break;
 case 'candidate-sample':pendingTrial=null;candidate=vision.sampleCandidate(doc());candidateSheet();break;
 case 'candidate-open':pendingTrial=null;candidate=clone(doc().candidates.find(c=>c.id===target.dataset.id));candidateSheet();break;
 case 'candidate-photo':case 'candidate-drawing':case 'candidate-overlay':document.querySelector('#candidate-preview').innerHTML=candidatePreview(a.slice(10));for(const b of portal.querySelectorAll('.segmented button')){b.classList.toggle('active',b.dataset.action===a);b.setAttribute('aria-pressed',String(b.dataset.action===a));}break;
 case 'keep-candidate':editor.apply('候補を保存',d=>{if(!d.candidates.some(c=>c.id===candidate.id))d.candidates.push(clone(candidate));});markDirty();dismiss();edit();await save();break;
 case 'discard-candidate':if(doc().candidates.some(c=>c.id===candidate.id)){editor.apply('候補の破棄',d=>{d.candidates.find(c=>c.id===candidate.id).status='discarded';});markDirty();}candidate=null;pendingTrial=null;dismiss();edit();toast('候補を破棄しました。採用図面・手動修正は保持しています');break;
 case 'adopt':if(pendingTrial){pendingTrial.start('ADOPT');}candidate.review={status:'reviewed',method:'user-adopt-action',at:new Date().toISOString()};if(candidate.status==='discarded')throw Error('破棄した候補は採用できません');editor.apply('候補を新規ページへ採用',d=>{if(!d.candidates.some(c=>c.id===candidate.id))d.candidates.push(clone(candidate));vision.adopt(d,candidate);});if(pendingTrial){trial=pendingTrial;trial.adopted(doc());pendingTrial=null;}markDirty();selected=null;dismiss();viewMode='drawing';edit();break;
 case 'format':format=target.dataset.format;exportScreen();break;case 'download':await output(false);break;case 'share':await output(true);break;
 case 'materials':materials();break;case 'settings':settings();break;case 'large-type':document.documentElement.classList.toggle('large-type');settings();break;
 case 'persist':toast(await store.requestPersistence()?'保存領域の保持が許可されました':'保持は端末判断です。案件バックアップも保存してください');break;
 case 'storage-info':{const e=await store.estimate();toast(`使用 ${Math.round((e.usage||0)/1048576)} MB / 上限の目安 ${Math.round((e.quota||0)/1048576)} MB`);break;}
 case 'check-update':if(swRegistration){await swRegistration.update();toast(swRegistration.waiting?'更新を適用できます':'更新確認が完了しました');settings();}else toast('オフライン機能は未準備、またはNativeモードです');break;
 case 'apply-update':if(editor&&savedRevision!==doc().revision&&!await save())return;swRegistration?.waiting?.postMessage({type:'ACTIVATE_UPDATE'});break;
 case 'install':await installPrompt?.prompt();installPrompt=null;settings();break;
 case 'import-vision-result':document.querySelector('#vision-result-input').click();break;
 case 'vision-diagnostics':diagnostics();break;
 case 'trial-download':await downloadOrShare(new Blob([JSON.stringify(trial?.report()||restoredTrialReport,null,2)],{type:'application/json'}),'VDRAW-photo-trial.json');break;
 case 'trial-assess':trial.assessment({missed:number('trial-missed'),misclassified:number('trial-misclassified'),shapes:number('trial-shapes'),attested:document.querySelector('#trial-attest').checked});try{await store.transaction('readwrite',x=>x.put(trial.report(),'vision-trial-'+doc().id),'meta');}catch{trial.recordPersistenceError='EVIDENCE_SAVE_FAILED';}diagnostics();break;
 case 'developer':sheet('開発・管理の状況',`<p>Visionジョブサービス：未接続<br>Claude / SAM：実推論0件<br>認証・費用管理：非公開CLI接続準備（未接続）<br>同期：未実装<br>Native Bridge：公式プラグイン・Androidプロジェクトを用意。実機未確認<br>APK：ビルド結果は検証成果物を参照<br>IPA：未ビルド</p>${editor?btn("import-vision-result","Vision結果ファイルを候補確認へ","file","secondary full"):""}${btn('vision-diagnostics','Vision Diagnostics','file','secondary full')}<p>Native機能状態：${esc(JSON.stringify(nativeHealth()))}</p><p class="muted">秘密情報はこの画面に入力しません。実AIを接続する際は非公開の認証済みサービスが必要です。</p>`);break;
 }}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target||target.disabled)return;if(target.classList.contains('panel-backdrop')&&performance.now()<suppressBackdropUntil){e.preventDefault();return;}try{await action(target.dataset.action,target);}catch(err){console.error(err);toast(safeNotice(err.message));}});
document.querySelector('#vision-result-input').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{if(!editor)throw Error('元資料を持つ案件を開いてください');if(f.size>5*1024*1024)throw Error('Vision結果は5MB以下にしてください');const envelope=JSON.parse(await f.text());candidate=vision.receive(doc(),envelope);pendingTrial=new TrialRecorder(envelope);candidateSheet();}catch(err){toast('Vision結果の読込失敗：'+err.message);}finally{e.target.value='';}});
for(const id of ['camera','photo','document'])document.querySelector('#'+id+'-input').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{toast('資料を端末内で読み込み中');const d=await importFile(file);if(editor&&savedRevision!==doc().revision&&!await save())return;dismiss();begin(d);if(d.importWarnings.length)toast(d.importWarnings.join(' '));}catch(err){toast('読込失敗：'+err.message);}finally{e.target.value='';}});
function attachGestures(){const stage=document.querySelector('#stage'),pointers=new Map();let initial=null,dragged=false,pinch=null,moved=null;
 const local=e=>{const r=stage.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top};};
 stage.addEventListener('pointerdown',e=>{if(e.button!==0)return;gestureBusy=true;e.preventDefault();const q=local(e);stage.setPointerCapture(e.pointerId);pointers.set(e.pointerId,q);
  if(pointers.size===1){initial={...q,view:clone(p().view),element:mode==='move'&&selected?clone(p().elements.find(e=>e.id===selected)):null};dragged=false;moved=null;}
  if(pointers.size===2){if(initial?.element){Object.assign(p().elements.find(e=>e.id===selected),initial.element);patchShape(selected);moved=null;}dragged=true;const [a,b]=[...pointers.values()],g=geometry(),mid={x:(a.x+b.x)/2,y:(a.y+b.y)/2};pinch={distance:Math.hypot(a.x-b.x,a.y-b.y),scale:p().view.scale,world:{x:(mid.x-g.tx)/g.k,y:(mid.y-g.ty)/g.k}};}
 });
 stage.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,local(e));
  if(pointers.size>=2&&pinch){const [a,b]=[...pointers.values()],mid={x:(a.x+b.x)/2,y:(a.y+b.y)/2},g=geometry();p().view.scale=Math.max(.25,Math.min(10,pinch.scale*Math.hypot(a.x-b.x,a.y-b.y)/Math.max(1,pinch.distance)));const k=g.fit*p().view.scale;p().view.x=mid.x-pinch.world.x*k-(g.r.width-p().canvas.width*k)/2;p().view.y=mid.y-pinch.world.y*k-(g.r.height-p().canvas.height*k)/2;draw();return;}
  if(!initial||pinch)return;const q=local(e),dx=q.x-initial.x,dy=q.y-initial.y;if(Math.hypot(dx,dy)>7)dragged=true;if(!dragged)return;
  if(initial.element){const g=geometry(),next=clone(initial.element);translate(next,dx/g.k,dy/g.k);Object.assign(p().elements.find(e=>e.id===selected),next);moved=next;}
  else {p().view.x=initial.view.x+dx;p().view.y=initial.view.y+dy;}if(initial.element)patchShape(selected);draw();
 });
 const finish=(e,cancel=false)=>{const q=local(e);pointers.delete(e.pointerId);if(pointers.size)return;gestureBusy=false;
  if(moved&&initial?.element){const next=clone(moved);Object.assign(p().elements.find(e=>e.id===selected),initial.element);if(!cancel){editor.update(selected,next);if(trial?.projectId===doc().id&&trial.pageId===doc().activePageId)trial.edit(initial.element,next);markDirty();}}
  if(!dragged&&!cancel&&initial&&viewMode!=='photo'){if(e.pointerType==='touch')suppressBackdropUntil=performance.now()+400;const g=geometry(),x=(q.x-g.tx)/g.k,y=(q.y-g.ty)/g.k,ids=p().elements.filter(e=>hit(e,x,y,14/g.k)).map(e=>e.id);if(ids.length>1)objectList(ids);else if(ids.length===1)objectSheet(ids[0]);else{selected=null;dismiss();}}
  if(dragged&&!cancel&&!moved){doc().revision++;markDirty();}const changed=!!moved;initial=null;pinch=null;moved=null;if(changed)patchShape(selected);draw();};stage.addEventListener('pointerup',e=>finish(e));stage.addEventListener('pointercancel',e=>finish(e,true));
 stage.addEventListener('wheel',e=>{e.preventDefault();const q=local(e),g=geometry(),wx=(q.x-g.tx)/g.k,wy=(q.y-g.ty)/g.k;p().view.scale=Math.max(.25,Math.min(10,p().view.scale*(e.deltaY<0?1.1:.9)));const k=g.fit*p().view.scale;p().view.x=q.x-wx*k-(g.r.width-p().canvas.width*k)/2;p().view.y=q.y-wy*k-(g.r.height-p().canvas.height*k)/2;draw();doc().revision++;markDirty();},{passive:false});
 stage.addEventListener('keydown',e=>{if(e.key==='Escape'){selected=null;mode='select';dismiss();}if((e.ctrlKey||e.metaKey)&&e.key==='z'){e.preventDefault();action(e.shiftKey?'redo':'undo',stage);}});
}
function resize(){const vv=window.visualViewport;document.documentElement.style.setProperty('--vh',(vv?.height||window.innerHeight)+'px');if(screen==='edit')draw();}
window.addEventListener('resize',resize);window.visualViewport?.addEventListener('resize',resize);resize();
window.addEventListener('beforeunload',e=>{if(editor&&savedRevision!==doc().revision){e.preventDefault();e.returnValue='';}});
window.addEventListener('online',()=>{if(screen==='settings')settings();});window.addEventListener('offline',()=>{if(screen==='settings')settings();toast('オフラインです。編集と端末保存は続けられます');});
