window.VDRAW={get trial(){return trial?.report()||restoredTrialReport},profile:take,store,vision,get uiBusy(){return busy},get editor(){return editor},get state(){return {screen,selected,mode,viewMode,savedRevision,saveState}},save,begin,exportFile,importFile,draw,action,back:handleBack};
